{
  "name": "Interson USB多普勒超声探头",
  "name_en": "Interson USB Doppler Ultrasound Probe",
  "manufacturer": "Interson",
  "description": "这是一类通过 USB 连接的超声探头，可进行常规超声成像，并支持多普勒相关采集，用于实验室或教学中的结构观察、流动现象监测和动态图像记录。根据具体探头结构，设备也可能包含用于机械扫描的内部电机。",
  "description_en": "This is a USB-connected ultrasound probe that performs standard ultrasound imaging and supports Doppler-related acquisition. It is used in laboratories or teaching environments for structural observation, flow-related measurements, and dynamic image recording. Depending on the probe design, the device may also include an internal motor for mechanical scanning.",
  "tag_hints": [
    "ultrasound imaging",
    "Doppler ultrasound",
    "USB ultrasound probe",
    "B-mode imaging",
    "flow measurement",
    "cine loop acquisition",
    "mechanical scan probe"
  ],
  "actions": [
    {
      "action_name": "auto-initProbe",
      "description": "初始化并配置超声探头。",
      "description_en": "Initialize and configure the ultrasound probe."
    },
    {
      "action_name": "auto-stopAcq",
      "description": "停止图像采集。",
      "description_en": "Stop image acquisition."
    },
    {
      "action_name": "auto-startAcq",
      "description": "开始图像采集。",
      "description_en": "Start image acquisition."
    },
    {
      "action_name": "auto-startDoppler",
      "description": "启动多普勒采集模式。",
      "description_en": "Start Doppler acquisition mode."
    },
    {
      "action_name": "auto-getImagesDoppler",
      "description": "获取多普勒图像帧。",
      "description_en": "Retrieve Doppler image frames."
    },
    {
      "action_name": "auto-getImages",
      "description": "获取常规超声图像帧。",
      "description_en": "Retrieve standard ultrasound image frames."
    },
    {
      "action_name": "auto-createLoopDoppler",
      "description": "生成多普勒图像循环序列。",
      "description_en": "Create a Doppler cine loop."
    },
    {
      "action_name": "auto-createLoop",
      "description": "生成常规图像循环序列。",
      "description_en": "Create a standard cine loop."
    },
    {
      "action_name": "auto-StartRun",
      "description": "启动设备运行或扫描流程。",
      "description_en": "Start the device run or scanning sequence."
    },
    {
      "action_name": "auto-startMotor",
      "description": "启动探头内部扫描电机。",
      "description_en": "Start the probe's internal scanning motor."
    },
    {
      "action_name": "auto-stopMotor",
      "description": "停止探头内部扫描电机。",
      "description_en": "Stop the probe's internal scanning motor."
    },
    {
      "action_name": "auto-fastMotor",
      "description": "将扫描电机切换到较高速运行。",
      "description_en": "Set the scanning motor to a faster speed."
    },
    {
      "action_name": "auto-getRawImages",
      "description": "获取原始图像数据。",
      "description_en": "Retrieve raw image data."
    },
    {
      "action_name": "auto-getUSBImages",
      "description": "通过 USB 获取图像数据。",
      "description_en": "Retrieve image data over USB."
    },
    {
      "action_name": "auto-progIt",
      "description": "向设备写入或加载程序化配置。",
      "description_en": "Program the device or load a programmed configuration."
    },
    {
      "action_name": "auto-BulkOut",
      "description": "通过 USB 批量输出通道向设备发送数据。",
      "description_en": "Send data to the device through a USB bulk-out transfer."
    },
    {
      "action_name": "auto-BulkIn",
      "description": "通过 USB 批量输入通道从设备读取数据。",
      "description_en": "Read data from the device through a USB bulk-in transfer."
    },
    {
      "action_name": "auto-ControlIn",
      "description": "执行从设备读取的 USB 控制传输。",
      "description_en": "Perform a USB control-in transfer from the device."
    },
    {
      "action_name": "auto-ControlOut",
      "description": "执行发送到设备的 USB 控制传输。",
      "description_en": "Perform a USB control-out transfer to the device."
    },
    {
      "action_name": "auto-InitOneA",
      "description": "执行一组特定的初始化步骤。",
      "description_en": "Run a specific initialization sequence."
    },
    {
      "action_name": "auto-Read512",
      "description": "读取 512 单位的数据块。",
      "description_en": "Read a 512-unit data block."
    },
    {
      "action_name": "auto-BulkOutTwo",
      "description": "向设备发送第二类批量输出数据块。",
      "description_en": "Send a second type of bulk-out data block to the device."
    },
    {
      "action_name": "auto-BulkOutTwo512",
      "description": "向设备发送 512 单位的第二类批量输出数据块。",
      "description_en": "Send a 512-unit second-type bulk-out data block to the device."
    },
    {
      "action_name": "auto-BulkOutFour",
      "description": "向设备发送第四类批量输出数据块。",
      "description_en": "Send a fourth type of bulk-out data block to the device."
    },
    {
      "action_name": "auto-BulkOutLarge",
      "description": "向设备发送大容量批量数据块。",
      "description_en": "Send a large bulk data block to the device."
    },
    {
      "action_name": "auto-readWrite",
      "description": "执行一次读写数据交换。",
      "description_en": "Perform a read/write data exchange."
    },
    {
      "action_name": "auto-Init1004",
      "description": "执行编号 1004 的初始化流程。",
      "description_en": "Run the initialization sequence identified as 1004."
    },
    {
      "action_name": "auto-InitOn",
      "description": "开启设备初始化流程。",
      "description_en": "Enable or start the device initialization process."
    },
    {
      "action_name": "auto-InitSeries10",
      "description": "执行 Series 10 相关初始化。",
      "description_en": "Run initialization for the Series 10 configuration."
    },
    {
      "action_name": "auto-InitArrays",
      "description": "初始化阵列或阵元相关配置。",
      "description_en": "Initialize array or transducer-element related settings."
    },
    {
      "action_name": "auto-InitRegisters",
      "description": "初始化设备寄存器设置。",
      "description_en": "Initialize device register settings."
    },
    {
      "action_name": "auto-freeze",
      "description": "冻结实时图像显示或采集。",
      "description_en": "Freeze live imaging or acquisition."
    },
    {
      "action_name": "auto-unfreeze",
      "description": "解除冻结并恢复实时图像显示或采集。",
      "description_en": "Unfreeze and resume live imaging or acquisition."
    },
    {
      "action_name": "auto-saveImage",
      "description": "保存当前超声图像。",
      "description_en": "Save the current ultrasound image."
    },
    {
      "action_name": "auto-DLImgs",
      "description": "从设备下载图像数据。",
      "description_en": "Download image data from the device."
    },
    {
      "action_name": "auto-checkAddress",
      "description": "检查指定地址是否可访问或有效。",
      "description_en": "Check whether a specified address is accessible or valid."
    },
    {
      "action_name": "auto-checkAddressFull",
      "description": "执行更完整的地址检查。",
      "description_en": "Perform a more complete address validation."
    }
  ]
}

